    def all_sub_services(self, pack_name: str) -> t.AsyncIterator[models.PackXdslService]:
        """all_sub_services iterates over GET /v1/pack/xdsl/{packName}/subServices (List the services contained in an xDSL pack).

        It lists the IDs with list_sub_services, then gets each object with get_sub_services,
        only when the loop reaches it. An object deleted in the meantime is skipped. Any other
        error is raised and stops the loop. Use it with ``async for``.

        Args:
            pack_name: The internal name of your pack

        The two calls require the IAM action packXdsl:apiovh:subServices/get.
        """
        return self._each(
            lambda: self.list_sub_services(
                pack_name,
            ),
            lambda listed_id: self.get_sub_services(pack_name, listed_id),
        )

